#include <unordered_map>
#include <queue>

class StockPrice {
private:
    std::unordered_map<int, int> timePrice;
    int maxTime = 0;
    std::priority_queue<std::pair<int, int>> maxHeap;
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> minHeap;

public:
    StockPrice() {}

    void update(int timestamp, int price) {
        timePrice[timestamp] = price;
        if (timestamp > maxTime) maxTime = timestamp;
        maxHeap.push({price, timestamp});
        minHeap.push({price, timestamp});
    }

    int current() {
        return timePrice[maxTime];
    }

    int maximum() {
        while (!maxHeap.empty()) {
            auto [p, t] = maxHeap.top();
            if (timePrice[t] == p) return p;
            maxHeap.pop();
        }
        return 0;
    }

    int minimum() {
        while (!minHeap.empty()) {
            auto [p, t] = minHeap.top();
            if (timePrice[t] == p) return p;
            minHeap.pop();
        }
        return 0;
    }
};

import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

class StockPrice {
    private Map<Integer, Integer> timePrice = new HashMap<>();
    private int maxTime = 0;
    private PriorityQueue<int[]> maxHeap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
    private PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);

    public StockPrice() {}

    public void update(int timestamp, int price) {
        timePrice.put(timestamp, price);
        if (timestamp > maxTime) maxTime = timestamp;
        maxHeap.offer(new int[]{price, timestamp});
        minHeap.offer(new int[]{price, timestamp});
    }

    public int current() {
        return timePrice.get(maxTime);
    }

    public int maximum() {
        while (!maxHeap.isEmpty()) {
            int[] top = maxHeap.peek();
            if (timePrice.get(top[1]) == top[0]) return top[0];
            maxHeap.poll();
        }
        return 0;
    }

    public int minimum() {
        while (!minHeap.isEmpty()) {
            int[] top = minHeap.peek();
            if (timePrice.get(top[1]) == top[0]) return top[0];
            minHeap.poll();
        }
        return 0;
    }
}

var StockPrice = function() {
    this.timePrice = new Map();
    this.maxTime = 0;
    this.prices = new Map(); // price -> count
    this.minPrice = Infinity;
    this.maxPrice = -Infinity;
};

StockPrice.prototype.update = function(timestamp, price) {
    if (this.timePrice.has(timestamp)) {
        const old = this.timePrice.get(timestamp);
        const cnt = this.prices.get(old) - 1;
        if (cnt === 0) this.prices.delete(old);
        else this.prices.set(old, cnt);
    }
    this.timePrice.set(timestamp, price);
    this.prices.set(price, (this.prices.get(price) || 0) + 1);
    if (timestamp > this.maxTime) this.maxTime = timestamp;
    if (price < this.minPrice) this.minPrice = price;
    if (price > this.maxPrice) this.maxPrice = price;
};

StockPrice.prototype.current = function() {
    return this.timePrice.get(this.maxTime);
};

StockPrice.prototype.maximum = function() {
    if (this.prices.has(this.maxPrice)) return this.maxPrice;
    let max = -Infinity;
    for (const p of this.prices.keys()) {
        if (p > max) max = p;
    }
    this.maxPrice = max;
    return max;
};

StockPrice.prototype.minimum = function() {
    if (this.prices.has(this.minPrice)) return this.minPrice;
    let min = Infinity;
    for (const p of this.prices.keys()) {
        if (p < min) min = p;
    }
    this.minPrice = min;
    return min;
};
